// fayl: src/middleware.ts
import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

// Ushbu funksiya foydalanuvchi har bir sahifaga kirganda ishlaydi
export function middleware(request: NextRequest) {
  // Brauzer cookie laridan 'token' ni izlaymiz
  const token = request.cookies.get('token')?.value;

  // Agar mijoz '/dashboard' yoki uning ichki manzillariga kirmoqchi bo'lsa...
  if (request.nextUrl.pathname.startsWith('/dashboard')) {
    if (!token) {
      // Token yo'q bo'lsa, uni majburlab '/login' sahifasiga jo'natamiz
      return NextResponse.redirect(new URL('/login', request.url));
    }
  }

  // Hamma shartlar to'g'ri bo'lsa, xotirjam sahifaga o'tkazib yuboramiz
  return NextResponse.next();
}

// Middleware qaysi manzillarda ishlashini belgilash (optimizatsiya uchun)
