import NextAuth from "next-auth"
import Credentials from "next-auth/providers/credentials"

const users = [
  { id: "1", name: "Aziza", email: "aziza@oshxona.uz", password: "12345", role: "admin" },
  { id: "2", name: "Bekzod", email: "bekzod@oshxona.uz", password: "54321", role: "user" },
]

export const { handlers, auth, signIn } = NextAuth({
  providers: [
    Credentials({
      credentials: { email: {}, password: {} },
      authorize: async ({ email, password }) => {
        const user = users.find((u) => u.email === email && u.password === password)
        return user ? { id: user.id, name: user.name, email: user.email, role: user.role } : null
      },
    }),
  ],
  pages: { signIn: "/login" },
  callbacks: {
    jwt({ token, user }) {
      if (user) token.role = user.role
      return token
    },
    session({ session, token }) {
      session.user.role = token.role
      return session
    },
    authorized({ auth, request: { nextUrl } }) {
      if (!auth) return false // kirmagan — /login'ga
      if (nextUrl.pathname.startsWith("/admin") && auth.user.role !== "admin") {
        return Response.redirect(new URL("/forbidden", nextUrl))
      }
      return true
    },
  },
})

